88	// 已有一个小朝向时，下一帧朝向增量为零必须保持原朝向，不能经过一次更新
89	// 就被清零。
90	func TestTinyHeadingSurvivesZeroIncrement(t *testing.T) {
91		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
92		res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
