package main

import (
	"fmt"
	"math"
)

func old(a float64) float64 {
	if a == 0 {
		return 0
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	a = math.Mod(a+math.Pi, 2*math.Pi)
	if a < 0 {
		a += 2 * math.Pi
	}
	a -= math.Pi
	if a >= math.Pi {
		a -= 2 * math.Pi
	}
	return a
}

func new_(a float64) float64 {
	if a == 0 {
		return 0
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	r := math.Mod(a, 2*math.Pi)
	if r >= math.Pi {
		r -= 2 * math.Pi
	} else if r < -math.Pi {
		r += 2 * math.Pi
	}
	return r
}

func main() {
	twoPi := 2 * math.Pi
	inputs := []float64{
		6.283185307179587,          // 2π + 8.88e-16
		math.Nextafter(twoPi, 4*math.Pi),  // just above 2π
		math.Nextafter(twoPi, 0),          // just below 2π
		-6.283185307179587,
		-math.Nextafter(twoPi, 4*math.Pi),
		-math.Nextafter(twoPi, 0),
		twoPi, -twoPi,
		math.Pi, -math.Pi,
		-math.Pi - math.Pi*math.Ldexp(1, -52),
		4 * math.Pi, 100 * math.Pi, -100 * math.Pi,
		1e-16, -1e-16, 1e300, -1e300,
		math.Nextafter(math.Pi, 4),        // just above π
		math.Nextafter(-math.Pi, -4),      // just below -π
	}
	for _, in := range inputs {
		o, n := old(in), new_(in)
		flag := ""
		if o != n {
			flag = "  <-- DIFF"
		}
		fmt.Printf("in=%.17g  old=%.17g  new=%.17g%s\n", in, o, n, flag)
	}
	// exact full circle must be zero
	fmt.Printf("new(2π)=%v new(-2π)=%v\n", new_(twoPi), new_(-twoPi))
}
